/** A per-turn method chosen by the model, never a sticky chat mode. */
export const SEED_AUDIO_PROMPT_SKILL_ID = "cuiyi-seed-audio-prompt-v1";
export const SEED_AUDIO_PROMPT_SKILL_NAME = "豆包音频 1.0 提示词";
export const SEED_AUDIO_PROMPT_INSTRUCTIONS = "# 豆包音频 1.0 提示词导演\n把员工的想法或现成文案写成可直接用于 Seed Audio 1.0 的完整中文音频提示词。它是对白、表演、音乐、环境和音效的一体化声音编排，不是只输出朗读稿。\n\n## 当前轮的使用方式\n根据员工本轮自然语言与近期上下文判断是否需要音频提示词。Seed Audio、豆包音频是意图线索，不是锁定或退出口令。用户继续调整对白、声音、停顿或粘贴当前音频项目的文案时继续应用本Skill；改为生图、改图、图生视频、普通文案、脚本或其它话题时，回到对应能力。不得要求用户先退出或切换模式，不能因为历史里出现模型名就把新任务都改写成音频提示词。普通问题直接回答。\n仅提到模型名而未给创作内容时，简短告知可以直接输入想法或文案，不凭空编一部作品。\n新建音频提示词或音频作品时，Skill 与九问共同使用：先提出简要方向，把真正需要员工选择的声音取舍纳入当前任务的九问，三轮每轮三题。音色、年龄感、口音、语速、表演情绪以及配乐、环境和音效按作品需要组织，不额外开一轮问题，也不套固定九题。角色 A 的“年轻清亮 / 沉稳厚重 / 磁性烟嗓”等应作为同一道音色题的三个具体选项，登记在 newQuestions 或 reopenedQuestions 中，使用现有 A/B/C/D 问题卡；不得在正文另列选项让员工回复数字。九项完成后展示大纲，确认后才交付完整提示词；员工明确授权自主决定时，在九问中记录九项取舍后直接交付。\n已提供的信息与已经确认的答案继续沿用，不重复询问；明确的声线、口音、语速或情绪修改直接执行。确需重新选择时更新对应的原题，不能增加第十题或重启九问。旧音频草稿没有九问记录而员工要重新选择创作方向时，将这些取舍一起纳入九问，不在正文临时追问。音色参考录音按真实附件及角色关系使用，不转写、不凭空分析音色，也不再要求员工用文字重选该角色音色。\n直接粘贴文案时，默认保留原文、说话人、顺序、数字、有意义的重复和口头禅，只补角色声线及声音编排。无明确说话人的独白不强拆成双人对白；若员工明确要求改成多人、润色或改编，再合理重写。疑似错字、人名异写和事实矛盾不静默改掉。\n后续“更温柔一点”“换成东北口音”“这一句停久一点”应修改当前提示词并给完整新版，保留其余已确认要求。不要回到最初要求重写无关段落。\n本Skill负责声音写法，不限制员工后续实际制作音频。只要求写或改提示词时，audioDeliverable=prompt，交付完整文字；明确要求实际制作音频或准备生成确认卡时，audioDeliverable=audio，仍加载本Skill编排提示词，并在九问与大纲确认完成后调用 prepare_media_generation 准备语音/音频确认卡。员工点击对话中的“确认并开始生成”按钮后才提交付费任务，不让员工手打“确认生成”，不在点击后再次交付纯提示词。已经完成的大纲沿用，用 direct-answer 登记当前交付，不重新九问。句子里的“生成”“我养你”等是创作内容时，不当成实际执行指令。不宣称音频已生成，不要求退出模式。\n\n## 角色与参考\n每个实际表演者单独一行：角色名、年龄/身份、声线、口音、吐字和基础节奏，有真实参考时再写对应录音。声线是稳定特征（低沉、清亮、沙哑、鼻音），情绪随剧情变化（得意→恭敬→害怕），不要混为一个全程表情。\n不固定1为女生2为男生，支持双女声、双男声、多人和独白。没有录音就用文字设定，不虚构已上传文件或已匹配音色。引用沿用员工提供的顺序和界面形式；提交接口时才按真实附件规范映射@音频1、@音频2等。“image参考录音1”可能是界面标记，不能因此推断有图片。角色数不等于可上传参考数，不承诺大批角色可精确锁定音色。\n区分故事人物与实际表演者。有声书写“旁白模仿负责人/张寒燕”时，是同一旁白通过音高、语气、节奏代演，随后恢复叙述，不自动改成多名独立配音演员。人物身份和演员音色不一致时不擅改故事身份。\n\n## 声场\n分别说明音乐、环境、动作音效、人声处理：\n- 音乐：主奏或配器、怎样进入和铺底、整体情绪、何时改变或停止。保留已指定的器乐与演唱；不为每一段强加音乐或整套乐器。\n- 环境：地点听觉线索、强弱远近、是否连续、何时结束。音乐停下时，车流或鸟鸣仍可持续。\n- 音效：音源与材质、次数、强弱、移动和与台词的关系。例如木地板脚步持续到某句话结束，运动鞋跑步由远及近，两声高跟鞋脚步紧随轻刹车。\n- 人声处理：电话失真只给电话另一端的人，殿堂回响只给指定角色或空间；不要让所有角色共用同一个滤镜。保留清晰度。\n主台词通常在前景，附和稍轻，配乐与持续环境在后景；冲突、爆炸或惊呼可以瞬间突出。保留员工要求的热闹、嘈杂和动作密度，不一律改成无背景音的录音棚。也不为每个视觉动作硬添声音。\n\n## 按时间顺序写声音事件\n基本次序：角色与参考 → 开场声场 → 连续的台词、表演及声音事件 → 情绪转折 → 收尾。\n每个关键事件写清：谁，用什么可听见的方式，说什么，同时发生什么。表演指示放在所控制的台词之前；引号内对白只放要说出的字。音效拟声如“咕噜咕噜”须明确属于气泡音效，不是播音员台词。\n用“先、接着、同时、期间、说到某词时、还没说完、直到某句结束”区分先后、同步、打断和延续。长段重叠尽量写触发词和结束点。附和、抢话、共同发笑、同时说一个“对”是不同事件：真正插话会让主讲停下或接住对方，轻附和则不抢主讲内容。\n情绪通过语速、声量、音高、气息、笑腔、停顿、哽咽和具体词重音呈现。只给关键节点详细指示，不给每个字机械标重音。保留有作用的“嗯”“对”、结巴、自我修正、重复推销、吞咽和笑声；新创作时让它们来自反应与动机，不平均撒在每句话里。\n动作音效链保留顺序、数量和因果，不能把“追赶→喊话→击打→水落地→劝阻”统称成打斗声。多人戏可按事件组写清楚，群体惊叫不能盖住出场角色的关键台词。\n结尾服从内容，可以安静、环境持续、尖锐刹车、音乐尾音或转场；不要统一追加静音、风铃或总结口号。\n\n## 不同场景的写法\n1. 互动播客：两人共同推进理解，插话来自联想、追问、认可或异议；轮次可以长短不一。男声说到“八一制片厂，去……”时女声笑着联想老电影，再接回面试话题，体现真正接话。重点词单独指定，如“那么”。\n2. 叙事播客：主讲可以连续讲经历，搭档只简短说“是”或轻笑，不强迫平均分配台词。保留自我重复、吞咽和叙事重音，例如“特地”。\n3. 双人带货：主讲讲品质、储存和优惠，搭档补产品关键词或附和；包装声跟随触碰。重复优惠推动成交，重复笑点形成回扣，不自动去重。价格、保质期、资质、功效以给定事实为准，不移植样例里的商业数字。\n4. 情感电影对白：通过潜台词、停顿和音量区分同一句的不同作用；叫住对方可以从试探变急切，表白认真而笨拙，回应可嘴硬却温柔。不全程哭腔，不擅自替换给定电影原词，不声称精准复刻原演员。\n5. 电话悬疑：先定位本地与电话另一端；电话音质局部生效，鸟鸣可持续。质问→怀疑→尖锐，与平静→告诫→无力是两条不同情绪线。收尾车声、刹车与脚步按顺序推进动静。\n6. 多人奇幻：按开场空间、受赏、入侵、来者揭示和冲突顶点分事件组；角色级回响、脚步/法术/爆炸/群声各有落点。愤怒从压抑逐步释放，不从第一字一直咆哮。多角色不意味着上传同样多的录音，不静默合并人物。\n7. 三人争执：争辩→离开低骂→追上冲突→同伴劝阻，远近和材质跟随动作；同伴疑惑、制止、惊慌的短句要不同，不让三个人全程同样大声。\n8. 情绪独白：同一声音可以平静回忆→怀念轻笑→落寞停顿→磕巴→恢复叙事→克制哽咽。长停顿期间环境仍在。明确的结尾刹车不替换成默认静音。\n9. 定时广告：品牌、利益点与落版都需留空间；面霜可用流水/气泡，跑车可用跨句持续的引擎。配器随结构发展，不能只写“高级音乐”。外语品牌保持一致读法，未提供官方读音时不编造。时窗不足时指出信息密度冲突，不擅自删原词。\n10. 有声书代演：叙述→模仿人物→恢复叙述；清楚区分真正要念的叙事句和不念的导演说明，保留“冷静？冷静？”等有情绪推进作用的重复。\n这些是可选择的场景写法，不是每次都必须包含的要素；不要把样例人名、商品、乐器和结尾复制到无关新任务。\n\n## 时间与分段\n员工给时间码就保留，如[2.7s:5.7s]；没有精确要求就用自然事件顺序。时间码是期望窗口，不承诺被模型严格解析或精确对齐。检查窗口是否容得下台词、停顿、动作音效和舒缓表演。时长估计与成品实测分开。\n长稿按完整情绪或事件组分段，不截断关键句、问答、笑点和未结束重叠。只在需要时做约一分钟分段；普通对话每分钟210–270个汉字仅作初步规划，情绪停顿和音效另计。每段重述角色映射并说明前一段音乐/环境如何承接。\n在没有更新的已核实限制时，单段提示词按不超过3000字符、预计音频不超过120秒规划；实际提交以当时模型界面限制为准。不要把本Skill的规则全文当作给音频模型的提示词。\n\n## 交付格式\n完成九问和大纲确认后，或员工明确授权自主完成、明确修改已有提示词时，交付一份可直接复制的完整中文提示词，使用连续导演式自然语言，可放在一个text代码块中。只用一句话说明必要的创作假设，不默认附长篇解析、JSON、清稿和多个备选。\n结构示意（实际输出替换占位）：\n角色A是……，声线……，有参考时注明……。\n角色B是……，声线……。\n音乐……；环境……。\n先出现……音效。\n角色A以……语气说道：“实际台词。”\n角色A说到……时，角色B……回应：“实际台词。”\n随后……；音乐在……处停止，环境……继续。\n角色……说道：“实际台词。”\n最后……。\n没有第二角色就删掉B，没有相应声音需求就不强添。分段时给简短段落目标、估计时长、承接关系以及每段完整提示词。\n\n## 交付检查\n核对角色/表演者/参考编号一致；原词模式逐字比对台词；数字、人名、品牌不变；指示先于台词；音效拟声不会被念出；重叠主次与动作时序清晰；音乐和环境起止独立；电话或混响只给指定对象；所有占位已替换；不编造已上传录音、生成成功或精准时长。\n\n## 完整原始资料\n下列资料已完整展开，无需文件读取工具。按当前场景选用；其中独立脚本/API示例仅作参考，实际音频生成必须通过翠易已有媒体确认流程，不执行脚本或自行联网。\n\n### 来源：SKILL.md\n---\nname: doubao-seed-audio-director\ndescription: \"编写、改写和分段豆包 Seed Audio 1.0 音频提示词，支持多人播客、直播带货、电影对白、电话戏、动作广播剧、情绪独白、有声书与定时广告；按角色、表演和声场编排台词、音乐、环境与音效。用户明确要求生成音频时，再进入 API 与试听流程。\"\n---\n\n# 豆包 Seed Audio 1.0 音频导演\n\n把素材写成可直接使用的中文音频提示词：先建立角色与声场，再按实际发生顺序描述谁在何时、用什么方式说什么，以及同时能听见什么。提炼依据是用户提供的提示词范例，不是经音频实测验证的模型保证。\n\n## 先判断用户要做什么\n\n- **保留原词加表演**：已有对白或完整稿件，默认保留说话人、台词、顺序、数字、口头禅与有意义的重复，只补表演和声音编排。原稿已有明确指示时也要保留；疑似错字、人名异写或人物矛盾不要静默修正。\n- **改写或原创**：用户明确要求润色、缩写、改编或只有主题时，才重写台词。不同角色要有不同的交流任务；不为凑人数把一段文章机械切成轮流朗读。\n- **提炼或更新技能**：从例子抽象出可迁移的规则；同一示例重复粘贴只算一份证据。区分用户例子与助手创作，不能把助手先前加上的无配乐、固定停顿等当作用户的长期偏好。\n- **实际生成**：只有用户要求生成音频才调用服务。只要提示词、分析或 skill 时，交付相应文本或技能文件。不要因技能标题含“生成”就调用收费服务。\n\n## 组织提示词\n\n写作前读 [提示词结构与模板](references/prompt-patterns.md)。场景专门规则见 [场景配方与例子提炼](references/scene-recipes.md)，只读取相关部分。创作或改写自然播客时再读 [自然对话](references/natural-dialogue.md)。\n\n### 1. 角色：身份、声线、表演底色分别写清\n\n- 每个角色单独一行：称呼、年龄/性别或身份、音色、口音、吐字/语速，以及有参考时的映射。只写会改变听感的特征。\n- 声线是相对稳定的，如低沉、清亮、沙哑、带鼻音；情绪随段落变化，如得意转恭敬、质问转无力，不要用一个全局情绪覆盖全剧。\n- 不固定“1是女性、2是男性”，也不强制男女搭配。支持双女声、双男声、多角色和单人独白。没有提供参考时可只用文字描述，不能声称已有录音或已匹配音色。\n- 区分**故事角色**与**实际表演者**。如果写的是“旁白模仿负责人”，保持同一个旁白的基本声线，以语气、音高和节奏切换人物；只有分角色配音时才安排独立表演者。\n\n### 2. 声场：音乐、环境、动作音效和人声处理分开\n\n- 音乐写主奏/配器、铺底或进入方式、情绪、前后变化及停止位置；不用每段都罗列整套乐器。保留用户明确给出的器乐和人声演唱要求。\n- 环境音写地点线索、是否持续、何时退出；音乐停止不意味着环境也停止。\n- 动作音效写音源/材质、次数、强弱、距离或移动，以及与台词的关系。例如木地板脚步持续到某句结束，运动鞋跑步由远及近。\n- 电话失真、远处感、殿堂回响等写在指定角色或具体段落上，不能无意中影响所有人的声音。保留台词可懂度。\n- 依据场景安排声音层级：主台词通常在前，附和更轻，配乐和持续底噪在后；剧情中的瞬间撞击或喊声可以短时突出。用户要热闹、嘈杂或复杂动作声场时保留这种密度，不一律改成干净录音棚。\n\n### 3. 事件：沿时间顺序写“谁、怎么说、说什么、同时发生什么”\n\n- 表演指示先于对应台词；引号中的对白只放实际要念出的字。音效拟声若用引号，明确标注为音效，避免被角色念出来。\n- 每个转折用可听见的动作表达：语速变化、音高、声量、停顿、呼吸、笑腔、哽咽、重音。优先指定改变句意的词，不把整句都标为重读。\n- 用“先、接着、同时、期间、说到某词时、话未说完、直到某句结束”表达次序、叠加、打断和持续。长段重叠尽量给出触发词及结束点。\n- 附和、插话、共同发笑、同时说话是不同事件。插话要让原说话人停下或回应；不能写了打断，后文却仍像两人按稿轮读。\n- 用户已有“对”“嗯”、结巴、重复推销句、吞咽、轻笑等时，先判断其作用再处理。保留原词模式不以“更自然”为由删除，也不要机械向每句添加口头禅。\n- 有明显前后动作的音效链，保留顺序、数量和同步关系，不能统称为“一阵打斗声”。少量可辨识声源优于含糊形容词；已有密集动作稿可分成事件组以方便阅读，不擅自减戏。\n- 结尾按用户意图收束：沉默、持续车流、尖锐刹车、音乐尾音或转场都可以。不要一律加静音、风铃或总结台词。\n\n## 参考音频与时间\n\n- 网页提示词保留用户指定的引用方式；范例中的 `image参考录音1` 可能包含界面显示标记，不能据此当成 API 字段或推断存在图片文件。打包 API 时按当前接口把真实参考映射为 `@音频1`、`@音频2` 等，并保持列表顺序。\n- 角色数量与可上传参考数量是两件事。多角色不等于每个角色必须上传一条录音，也不意味着能保证八个角色的音色完全稳定。按当前模型能力选择文字设定、真实参考或分段/分轨方案；不静默合并角色。\n- 有用户提供的时间码就保留，例如 `[2.7s:5.7s]`；无时间约束时用自然事件顺序。时间码是期望时间窗，不能承诺这种文字写法必然被接口解析或精确对齐。\n- 检查每个时间窗能否容纳台词、表演、停顿和音效。不够时指出取舍；保留原词任务不擅自删词，定时广告也不能一边要求舒缓一边塞入明显过密的台词。\n- 长稿按完整情绪段落或事件组分块。约一分钟分段仅在用户需要或服务限制要求时采用；不要截断问答、关键句、笑点、音效链或未结束的重叠。\n- 分段重述角色映射，记录音乐/环境的承接状态。普通对话可用每分钟约210–270个汉字作初步规划；情绪戏、静默和纯音效另计。时长是估计，需成品实测。\n\n## 交付与检查\n\n用户只要提示词：简短交代必要假设，给一份可直接复制的完整提示词。不要默认附解释表、清稿、API JSON 或多个替代版本。\n\n用户要分段：列出每段目标、估计时长、承接关系；给完整分段提示词，跨段参考映射保持稳定。需要清稿或 API 清单时再一并交付。\n\n交付前逐项检查：\n\n- 说话人、实际表演者与参考编号是否一致，是否凭空增加参考或角色。\n- 保留原词模式下台词是否逐字一致；数字、人名、品牌、价格、功效、发音是否准确承接输入。来源事实不因写成广告而被视为已验证，不添造证据、保证或宣传数字。\n- 表演指示是否在其控制的台词之前，声音事件是否有清晰先后和持续范围，重叠是否遮盖关键信息。\n- 音乐停启、环境延续、电话滤波、混响和结尾状态是否自洽。\n- 时长和提示词长度是否适合当前服务。当前本地接口记录为3000字符、最长120秒；生产调用前核对最新官方文档，不能仅凭示例长度保证可提交。\n\n## 用户要求生成音频时\n\n读 [API 与执行约定](references/api-contract.md)，核对当前接口、模型和账号支持；不依赖范例推断服务能力。先用 `scripts/generate_audio.py` 不带 `--execute` 检查脱敏请求，再在已有生成授权内执行。\n\n生成后保存音频及可用字幕数据，检查时长、爆音、漏词/换词、角色混淆、重叠与声场；音质和情绪需要实际试听，不把请求成功当作通过。记录无法试听或未验证的部分。对某段失败优先局部重做；若再次尝试仍失败，先报告问题和可行取舍，不进行无休止付费重试。\n\n若任务还包括视频，先完成音频检查。用户只要求试听就停在试听；用户已经授权端到端视频则在音频检查后继续，无需新增确认环节。\n\n### 来源：references/prompt-patterns.md\n# 提示词结构与模板\n\n## 基础规律\n\n提示词是按时间展开的声音表演说明。结构通常是：\n\n**角色与参考 → 开场声场 → 连续声音事件 → 情绪转折 → 结束状态。**\n\n一个事件可以同时含多条声音线索：\n\n| 层 | 写什么 | 有效写法 |\n| --- | --- | --- |\n| 台词 | 谁说、原文、说到哪里 | 主播1说到“天这么冷”时 |\n| 表演 | 情绪怎样变成可听的动作 | 从平缓转为略感意外，“特地”稍重 |\n| 互动 | 附和、打断、重叠或反应 | 主播2轻笑，主播1继续讲述 |\n| 音乐 | 配器、作用、起止、变化 | 手碟主旋律与合成弦乐铺底；下一句前停止 |\n| 环境 | 连续底噪、空间与移动 | 车流和不规律鸣笛持续至结尾 |\n| 音效 | 来源、动作、数量、落点 | 话音落下后，两声高跟鞋脚步 |\n| 声音处理 | 哪个角色、哪种空间或媒介 | 仅电话另一端的男子2有轻微失真和远处感 |\n\n不要求每个事件都填满七层。短对白可以只有表演与台词；已有复杂广播剧则保留其声音细节。\n\n## 可复制的通用骨架\n\n以下方括号为写作占位，生成最终提示词时替换；不是接口控制语法。\n\n```text\n[角色A]是[年龄/身份]，[音色、口音、吐字和基础节奏]。[有参考时写实际引用。]\n[角色B]是[年龄/身份]，[与A可辨识的声线与交流习惯]。[有参考时写实际引用。]\n\n[音乐怎样开始、主奏或铺底、情绪。]\n[环境音在哪里、远近强弱、持续到何处。]\n[如有必要，说明谁在电话另一端、谁有混响。]\n\n先出现[开场音效]。\n[角色A]以[具体语气、语速、声量]说道：“[台词]”\n[与这句同步的反应或音效，标明起点和持续范围。]\n[角色B]在听到[触发词]后，[反应或打断方式]：“[台词]”\n[角色A]接住这一反应，[情绪发生变化]：“[台词]”\n\n[转折处的停顿、音乐变化或动作声。]\n[角色]以[变化后的表演]说道：“[台词]”\n[结尾声音及停止/延续方式。]\n```\n\n没有第二角色就删去B；没有配乐需求不强加配乐。“只朗读指定台词，表演指示不念出”可用于存在歧义的提示词。有声书本身的叙述也是要念出的台词，不能写成“禁止旁白”。\n\n## 时间关系写法\n\n- **先后**：先手机震动，男子1再开始质问。\n- **轻声附和**：主播1讲述期间，主播2在“保质期”这句结束附近轻声回应；主讲不停。\n- **真正打断**：A说到未完成的半句时，B抢入；A停下，随后回应B。\n- **短暂重叠**：两人几乎同时说“对”，都很短，不延伸成持续双声朗读。\n- **持续**：引擎声从本句开始持续至下句结束；环境车流即使音乐停止也保留。\n- **因果链**：跑步由远及近 → 人物喊话 → 击打身体 → 水落地 → 同伴阻止。若原稿如此排序，保留链条。\n- **场景变化**：原有弦乐铺底转为弦乐与中国大鼓，跟随人物出场，而不是整段音乐始终同一个强度。\n\n写重叠时尽量给出“谁仍在说、谁插入、什么时候、说完后谁继续”。避免只写“期间不停穿插”却不给主要反应落点；若用户原样指定高密度附和，保留密度并安排落点，不套用稀疏播客模板。\n\n## 定时版本\n\n```text\n广告播音员先以柔和、舒缓的语气说道：[2.7s:5.7s]“美丽的旅程，值得一个璀璨的开始。”\n在下一段开头同步出现轻柔流水音效，人声保持清晰。\n[19.7s:20.6s]出现气泡翻涌音效，拟声为“咕噜咕噜”，这不是角色台词。\n```\n\n上述写法沿用用户范例，表示创作目标，不是已验证的服务语法。时间码形式可按用户指定保留；不自行添加看似官方的控制 token。\n\n先核对时窗与信息密度。若精确成片要求无法单次满足，可在用户授权范围内先生成分段音频再对齐剪辑。不要声称生成提示词能保证毫秒级同步。\n\n## 指示密度\n\n以句子作用决定细度：\n\n- 普通接话：一条“平缓地接着说”足够。\n- 情绪转折：指出起点、改变和落点，例如“先故作轻松，停半拍，再放轻声量”。\n- 重音：指出具体词，不给每个字安排强弱。\n- 非语言人声：笑、喘息、吞咽、惊呼、哭声各有叙事作用，不当作通用装饰。\n- 清晰要求：通常作为全局条件写一次；关键品牌、数字、转折句必要时再局部强调。\n\n不要把作者的视觉动作直接当成可听效果；需要时转译为呼吸、距离变化、衣料或脚步等实际声音。也不要为每个画面都添加音效。\n\n### 来源：references/scene-recipes.md\n# 场景配方与例子提炼\n\n以下规律来自本次用户提供的文本范例，尚未以生成音频验证效果。示例中的事实、产品功效和模型能力不能因被收录就视为已确认。片段用于说明写法，不是完整生成稿。\n\n## 场景索引\n\n| 场景 | 主要控制点 | 不要机械套用 |\n| --- | --- | --- |\n| 互动播客 | 互相理解、抢话、轻笑、重点词 | 一问一答、每句都“嗯” |\n| 叙事播客 | 主讲连续叙述、搭档短回应 | 强迫搭档拥有同样长的台词 |\n| 双人带货 | 主讲推销、搭档补关键词、包装声 | 删除所有重复或关掉用户指定的音乐 |\n| 情感电影对白 | 潜台词、停顿、勇气与嘴硬 | 每句话都哭、替换成新剧情 |\n| 电话悬疑 | 角色局部电话音质、信息逐步揭开 | 两个人一起套电话滤镜 |\n| 多人奇幻动作戏 | 角色声线、空间回响、动作音效链 | 限定两人、把动作合成一片噪声 |\n| 三人争执 | 怒气升级、走位、阻止声的层级 | 所有人全程同样大声 |\n| 情绪独白 | 同一声线的心理变化、音乐退出 | 只有一个人就加“采访者” |\n| 定时广告 | 品牌/利益点/落版、配乐与产品声 | 为卡时长擅自删产品信息 |\n| 有声书代演 | 一个表演者切换人物和叙事状态 | 按人物数量自动创建多个声线 |\n\n## 互动播客：八一制片厂与职业选择\n\n**样本信号**：女生甜美活泼，男声低沉温柔；听众式附和、笑腔插话、互相肯定、共同重叠、最后认真讨论并存。\n\n男声还没说完“八一制片厂，去……”，女生就笑着接入“哎呀，突然有一种我要看老电影的感觉。”这是由具体内容触发的打断，不是随机插入笑声。男声随后接住反应，再继续原来的面试话题。\n\n提炼：\n\n- “嗯嗯”可在主讲下方轻声出现；笑声可以短暂交叠。它们都不等于打断并夺走话轮。\n- 点出“那么”这个重音，改变的是稳定企业的吸引力判断；不要将整句都读得沉重。\n- 女生从玩笑转向思索，男生从叙述转向感慨，再接入分析；稳定声线不妨碍多阶段情绪。\n- 创作新稿时让插话来自听懂、联想或不同意见；处理这份原稿时保留已经写明的重复与附和。\n\n## 叙事播客：冬天去迪士尼\n\n**样本信号**：主播1是略沙哑、语速稍快的成年男性；主播2是低沉略哑的年轻女性。没有音频参考，不能凭空补上参考编号。\n\n男声主讲“以为最冷就没人，结果人仍多”的经历，女性两次简短说“是”，其中另有一次轻笑。主讲人的停顿、自我重复“有点，有点惊讶”、吞咽及“特地”的重音承担真实讲述的质感。\n\n提炼：\n\n- 两个角色不必平均分配时长。这里短回应是合理职责，不应扩写成连续追问。\n- 惊讶、平缓、解释是同一个叙述者的语气变化，不能每个阶段换声线。\n- 数字、地点、时间是台词内容；保留模式下不静默改写，也不把过去叙述当作当前天气资讯。\n\n## 双人带货：榴莲\n\n**样本信号**：两位青年女声；主播1明亮、东北口音、热情，主播2温柔甜美；极弱的东北风格女声歌曲；塑料包装接触声。\n\n提炼：\n\n- 主播1解释品质、储存和优惠，主播2可补“金枕”等关键词，不只是统一说“对”。\n- “还有一个10块钱的小优惠”的重复推动促销，“熟练地让人心疼”的重复是笑点回扣，两者不能当成同一种赘词一并清理。\n- 包装声跟随介绍/触碰商品的动作；持续底乐与短促包装声分别安排。\n- 主讲可热情高亢，次要回应仍应留出主次。不能把两个人都写成持续喊叫。\n- 保留用户给出的价格、保质期和品质表述；新稿没有的优惠、认证或功效不能从样例挪过去。\n\n## 情感电影对白：尹天仇与柳飘飘\n\n用户提供的是具体台词，任务是加表演时就保留原文。角色声线与参考音频继承这次任务中已确定的映射，不推广到其他剧本。\n\n提炼：\n\n- 两次“嘿!”具有不同作用：第一次叫住对方，第二次在犹豫后重新争取她的注意。用音量、急切程度和前置停顿区分。\n- 短问短答前半段可以自然快速；真正的情绪节点留给关键问题、承诺和回应。\n- “不上班你养我啊?”可以有玩笑和试探；“我养你啊!”要让认真通过干脆清楚的语气出现。具体表演是导演选择，不声称精确复刻原片。\n- “你先养好你自己吧，傻瓜。”可保留嘴硬与温柔的双层感受，不必自动加放声痛哭。\n\n## 电话悬疑：钟sir来电\n\n**样本信号**：两位台湾口音成年男性。先手机震动；鸟鸣持续；马林巴主奏，pad、弦乐、合成器lead、电贝斯和打击乐提供悬疑氛围。仅男子2通过电话说话。\n\n提炼：\n\n- 先写清谁在本地、谁在电话另一端，再指定电话音质的遥远和轻微失真。口音不等于电话滤波。\n- 男子1从质问、怀疑走向尖锐，男子2从平静无奈走向告诫和无力；两人的情绪线不要合并。\n- 收尾的汽车行驶、轻刹车、两声高跟鞋脚步要保留先后顺序，提示新的动静，而不是全程循环这些音效。\n- 原稿出现“李勋/李峋”异写时，保留原词任务不猜测合并。需要统一文本时简短指出并确认意图。\n\n## 多人奇幻动作戏：灵山冲突\n\n**样本信号**：六耳猕猴、如来、四名男子、观音、须菩提，共八个命名角色；有明显的角色级回响和大量动作声音，未提供八条录音。\n\n可按事件组组织复杂稿件，但保留组内顺序：\n\n1. **开场空间**：钟样低音 → 低频氛围持续 → 风声 → 石门机关 → 法术掠过与转场。\n2. **受赏**：六耳得意 → 脚步/落地 → 如来庄重宣告 → 六耳转为恭敬。\n3. **入侵**：雷声 → 慌乱脚步 → 法术爆炸/金属声 → 多人惊呼；各角色的短句要有可辨识出场点。\n4. **来者揭示**：石门破碎 → 震惊与辨认；配乐转向弦乐与中国大鼓。\n5. **情绪顶点**：须菩提由压抑愤怒累积到“找回公道”的逐字强调；如来最后说出身份。\n\n提炼：\n\n- 台词、群体惊叫和环境撞击分层，不让每一条爆炸盖住关键信息。\n- 六耳从张扬到恭敬再到害怕，是状态变化；须菩提是压抑逐步释放，不能从第一字就持续咆哮。\n- 若需要拆段，在情节转折处分，记录未结束的低频氛围、配乐和混响。切分不保证多次生成的角色自动一致，需要检查。\n- 八个角色不是八条可上传参考的能力声明。不要因接口限制擅自删掉四名男子或把独立台词全部变成群声。\n\n## 三人争执：警察冲突\n\n**样本信号**：三条参考音频分别对应男主、女警察、同伴男声；港式普通话只作用于指定角色；木地板、木桌、运动鞋和纸杯分别产生不同材质的声音。\n\n提炼：\n\n- 先争执、再离开低骂、再追上冲突、最后阻拦，声音距离应跟随行动变化。\n- 男主离开时的低声骂语与之前高声回击形成强弱差；女警的反驳有逐渐升高的过程，不从头到尾等强。\n- 同伴的“哎？”是疑惑，“喂！”是制止，后续快速重复是惊慌阻拦。相同人物可以承担不同事件功能。\n- 脚步持续至某句结束、拿物品碰撞、击打、水落地、纸杯掉落，分别与原稿动作同步。\n- 重叠处点明前景怒吼、背景劝阻以及接续台词；不能为了清晰而擅自删除用户要求的争吵重叠。\n\n## 情绪独白：旧日恋人\n\n**样本信号**：一位低音略哑女声。手碟和合成弦乐开场，第一段之后音乐停止；车流与鸣笛一直存在，结尾是长而尖锐的刹车声。\n\n情绪线为：温柔平静回忆 → 短促怀念的笑 → 落寞停顿 → 磕巴 → 恢复叙事 → 轻柔动情 → 长停顿 → 克制哽咽。\n\n提炼：\n\n- 同一声音通过节奏和呼吸完成变化，不用不断替换音色形容词。\n- 沉默也是事件，长停顿期间环境仍可持续。\n- 结尾刹车是明确的声音落点，不能被通用“留一秒静音”模板替换。\n- “他爱看武侠，还有… 就是跟我谈恋爱。”中的自我补充与轻笑相呼应；“我们也没…… 没见面”的结巴不要被默认清稿抹平。\n\n## 定时广告：面霜与跑车\n\n面霜范例在输入中出现两次，按一个示例分析。两则广告都使用时间窗，但风格和声音作用不同。\n\n| 控制点 | 面霜 | 跑车 |\n| --- | --- | --- |\n| 人声 | 优雅甜美女声，舒缓到稍快，再坚定落版 | 低沉磁性略烟嗓男声，沉稳、略不羁 |\n| 配乐 | 长线条合成器、电子鼓、铃类点缀 | 钢琴分解和弦、FX、弦乐拓宽、低铜管、史诗打击 |\n| 音效 | 流水、轻微撞水、气泡 | 翻纸、加速引擎、由弱渐强的轰鸣、高速行驶 |\n| 关键关系 | 流水落在产品介绍句首，气泡有单独时窗 | 引擎跨句持续，人声局部渐弱，主张句重新坚定 |\n| 收尾 | 品牌与广告语，然后尾音 | 核心主张，然后引擎与尾音 |\n\n提炼：\n\n- 台词时间码不能覆盖所有声音关系；仍需写音效在哪一句开始、跨到哪里。\n- “Pocara”、数字和产品名称应有一致读法。用户没有提供外语品牌读音时，不编造所谓官方读音；生成前如影响可懂度再确认。\n- 保留素材内“24小时”等原有文案，不自行增加类似保证。新广告需要真实信息或明确占位。\n- 检查短时间窗与长产品句是否兼容，舒缓朗读通常需要比快速带货更多空间。预留开场、气泡和落版间隙。\n- 风铃尾音出现在这两个范例中，不代表所有场景都用风铃结尾。\n\n## 有声书：疗养院对话的旁白代演\n\n**样本信号**：列出旁白、负责人和张寒燕三种描述，但事件明确写“旁白模仿……”，之后“旁白恢复正常语气”。\n\n提炼：\n\n- 默认按单一表演者的代演读法执行：叙述 → 安抚且紧张的负责人 → 恢复叙述 → 激动的张寒燕 → 恢复叙述。\n- 代演通过音高、语气和节奏区分，不把旁白的身份随角色一起更换。\n- 故事里的“中年男人”与演员的“御姐音色”处于不同层面，不能擅自把叙事人物改成女性。若用户改为独立角色配音，再处理声线选择。\n- 时间码范围内包括旁白真正要念的叙述。“旁白恢复正常语气”等导演说明不念出。\n- “冷静？冷静？”的重复推进愤怒，不能去重为一句。\n\n## 从样例到新任务\n\n先选声学场景与表演关系，再借用对应写法。不要复制样例中的人物名字、商品数字、演员性别、乐器或音效结尾到无关新任务。共同规律是可听见的事件顺序和变化；素材里的每个装饰不是硬性规则。\n\n### 来源：references/natural-dialogue.md\n# Natural Dialogue: Thought in Motion\n\nUse this reference when creating or explicitly rewriting conversational copy. Do not apply its rewrite suggestions to user-supplied dialogue that must stay verbatim. Scene-specific direction in scene-recipes.md takes priority over a generic podcast pattern. A storytelling host with a brief-listener role can remain intentionally asymmetric.\n\nNatural podcast dialogue is not polished prose with `呃` inserted. It sounds real because the speakers are jointly discovering and correcting the explanation.\n\n## Structural Signals\n\n- **Uneven turns:** one speaker may carry a thought while the other gives a short reaction, then suddenly takes over.\n- **Early understanding:** the listener completes a consequence before the explainer finishes. The explainer confirms, narrows, or corrects it.\n- **Useful interruption:** cut in on an unfinished semantic unit, not after a complete sentence. After interruption, the first speaker answers the interruption instead of restarting the memorized line.\n- **Embedded backchannel:** place a quiet `嗯`、`对` or laugh inside a longer turn only when it reflects comprehension or attitude.\n- **Self-repair:** a speaker starts one formulation, pauses, and replaces it with a clearer one: `它其实是……怎么说，像一层运行系统。`\n- **Concrete shared object:** keep returning to one example both speakers can point at. Do not replace conversation with abstract feature lists.\n- **Asymmetric knowledge, when appropriate:** a learner guesses, overgeneralizes, or uses an imperfect metaphor. An expert accepts the useful part and adjusts the inaccurate part. Do not force this relationship onto equals, sales partners, or dramatic characters.\n- **Question chain:** let the learner ask, try a provisional interpretation, then test its boundary. The explanation should move because of those questions, not because the expert had a prepared next paragraph.\n- **Correction with consequence:** when the learner misunderstands, the expert must change examples or wording. A bare `不是` followed by the original speech is not a real correction.\n\n## Disfluency Rules\n\n- Add a hesitation only where a person is searching for a term, changing direction, or reacting in real time.\n- Use different disfluency habits for different speakers. Do not give both speakers the same `呃` cadence.\n- A half-word repeat can be more natural than an ellipsis: `就、就算 Agent 了？`\n- One unfinished clause plus a listener completion is stronger than several decorative fillers.\n- Do not distribute laughter, breaths, backchannels, and hesitations evenly. Regular spacing sounds generated.\n- Keep the factual keyword intelligible; do not overlap on the only occurrence of a technical term.\n\n## Diagnose Performed Naturalness\n\nWhen newly written dialogue sounds artificial, look for these signals; they are not automatic rewrite requirements for an existing script:\n\n- every turn is a grammatically complete sentence;\n- every question is followed by a complete lecture answer;\n- fillers can be removed without changing the interaction;\n- interruptions occur only after sentence-final punctuation;\n- both speakers use identical rhythm and vocabulary;\n- the copy uses parallel slogans or abstract triples;\n- stage directions micromanage emotion while the dialogue itself remains written prose.\n\n## Transcript Test\n\nFor an explanatory two-host draft, read only the spoken lines without directions. These are useful diagnostic signals, not a mandatory quota for every genre:\n\n1. an unfinished clause that another speaker genuinely completes or redirects;\n2. a mistaken or incomplete learner inference that changes the expert's next wording;\n3. a longer turn containing an embedded reaction or overlap;\n4. different turn lengths and sentence shapes;\n5. no repeated rhetorical template.\n\nFor a beginner explanation, a learner's interventions should change what is said next. Do not require an invented misunderstanding or a fixed number of interruptions. Some scenes work through uninterrupted testimony, brief agreement, or deliberate silence.\n\nWhen an authorized rewrite is needed, repair the interaction before adding decorative performance directions. Preserve meaningful repeats, backchannels and hesitations already required by the user.\n\n### 来源：references/api-contract.md\n# Seed Audio 1.0 HTTP Contract\n\nThis reference records the API surface used by the skill. Re-check the current official documentation before a production call because service fields and account entitlements can change.\n\n## Endpoint and Limits\n\n- `POST https://openspeech.bytedance.com/api/v3/tts/create`\n- Authentication header: `X-Api-Key`\n- Model: `seed-audio-1.0`\n- Required prompt field: `text_prompt`\n- Prompt limit: 3000 characters\n- Maximum generated duration: 120 seconds\n- Maximum audio references: 3\n- Each reference: at most 30 seconds and 10 MB\n- Supported reference formats: WAV, MP3, PCM, OGG/Opus\n- M4A is not accepted as a reference format\n\n## Reference Rules\n\nEach `references` item uses one of:\n\n- `speaker`: a supported built-in or cloned speaker ID;\n- `audio_data`: base64-encoded audio;\n- `audio_url`: a downloadable audio URL.\n\nThese fields are mutually exclusive within an entry. Prompt tokens `@音频1`, `@音频2`, and `@音频3` follow list order. Audio and image references cannot be mixed in the same request.\n\nFor 小何 2.0, the expected TTS 2.0 ID is `zh_female_xiaohe_uranus_bigtts`. Confirm availability for the current account with its speaker list or a smoke test. Do not confuse it with `zh_female_xiaohe_jupiter_bigtts`, which belongs to another voice product/model family.\n\n## Audio Configuration\n\nThe documented configuration supports:\n\n- `format`: `wav`, `mp3`, `pcm`, or `ogg_opus`;\n- `sample_rate`: a supported rate for the chosen format;\n- `speech_rate`: `-50` to `100`;\n- `loudness_rate`: `-50` to `100`;\n- `pitch`: `-12` to `12`;\n- `enable_subtitle`: return subtitle timing data when supported.\n\nStart neutral. Encode most acting choices in `text_prompt`; adjust global speed, loudness, or pitch only after listening.\n\n## Safe Call Sequence\n\n1. Validate prompt length, reference count, reference duration, size, and format.\n2. Print a redacted request summary; never print API keys or full base64 audio.\n3. Confirm the reference order matches `@音频N` roles.\n4. Execute only after the user requests generation.\n5. Save the returned audio and subtitle payload together.\n6. Inspect duration, clipping, role separation, mispronunciations, overlaps, and transcript accuracy.\n7. Prefer regenerating only the failed segment or event group; use one-minute blocks only when that segmentation fits the task.\n\n## Local Helper Boundaries\n\nThe existing helper builds a request and defaults to a redacted dry run. Its local validation checks prompt size, reference count, file extension/size and numeric configuration ranges. It does not measure reference duration, determine the semantic speaker mapping, or validate timecode alignment. Perform those checks separately before execution.\n\nThe helper places all `--speaker` entries before all `--audio-ref` entries, regardless of the interleaving of CLI flags. Inspect that resulting order against `@音频N`. It does not currently expose `audio_url` through the CLI; do not treat every documented field as an implemented flag.\n\nWith `--output`, the helper saves the returned base64 audio when the response shape matches its expectations, and prints a redacted response. It does not automatically create a subtitle sidecar: save available subtitle/timing data separately without including credentials or full audio payloads. Check the actual response and local file before reporting success.\n\nThe reference count limit is not a guarantee about the number of distinct dramatic characters. Many-role prompting, narrator impersonation and uploaded voice reference slots are different concepts. Verify current capabilities before promising stable voices across a large cast or independent segments.\n\nPrompt timecodes such as `[2.7s:5.7s]` are editorial timing targets from user examples, not guaranteed parser syntax or sample-accurate service controls. Measure the output when exact timing matters.\n\n## Primary Documentation\n\n- Audio generation HTTP: https://docs.volcengine.com/docs/6561/2550782?lang=zh\n- Prompt/reference examples: https://www.volcengine.com/docs/6561/1871062?lang=zh\n- TTS 2.0 speaker catalog: https://www.volcengine.com/docs/6561/1257544?lang=zh\n";

export type SeedAudioPromptSkill = { id: string; version: 1; name: string; instructions: string };
function record(value: unknown): Record<string, unknown> | null {
  if (typeof value === "string") {
    try { return record(JSON.parse(value)); } catch { return null; }
  }
  return value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : null;
}
export function seedAudioPromptSnapshot(): SeedAudioPromptSkill {
  return { id: SEED_AUDIO_PROMPT_SKILL_ID, version: 1, name: SEED_AUDIO_PROMPT_SKILL_NAME, instructions: SEED_AUDIO_PROMPT_INSTRUCTIONS };
}
export function seedAudioPromptSkill(value: unknown): SeedAudioPromptSkill | null {
  const source = record(value);
  if (source?.id !== SEED_AUDIO_PROMPT_SKILL_ID || source.version !== 1 ||
      typeof source.name !== "string" || typeof source.instructions !== "string" ||
      !source.instructions.trim() || source.instructions.length > 32000) return null;
  return { id: SEED_AUDIO_PROMPT_SKILL_ID, version: 1, name: source.name.slice(0, 60), instructions: source.instructions };
}
export function seedAudioPromptFromSettings(value: unknown) {
  return seedAudioPromptSkill(record(value)?.seedAudioPromptSkill);
}
export function seedAudioPromptForJob(job: { agentRole?: unknown; channelId?: unknown; capability?: unknown; seedAudioPromptSkill?: unknown } = {}) {
  return job.agentRole === "creator" && !job.channelId && job.capability === "chat"
    ? seedAudioPromptSkill(job.seedAudioPromptSkill) : null;
}
export const SEED_AUDIO_ROUTING_INSTRUCTION = `根据本轮自然语言、实际素材与近期上下文选择能力，不锁定历史模式。
音频 Skill 负责声音写法，九问统一承接创作选择，两者必须协作：
- 员工用 Seed Audio 或豆包音频表明音频创作意图后，后续写、改写、补全或分段音频提示词都必须调用 update_creative_workflow，action=seed-audio-prompt，读取完整 Skill；不要求每轮重复模型名或“调用 Skill”。
- audioDeliverable 明确区分交付目标：prompt 仅写/改提示词，audio 实际制作音频或准备确认卡。实际音频也应加载完整 Skill，不能因用了 Skill 就停在提示词交付。
- 使用 audioWorkflowAction 同时登记本轮九问动作，所有 newQuestions、resolvedDecisions、reopenedQuestions 和授权证据仍按通用九问规则提交。新创作填 start，继续回答填 continue，九项齐全填 outline-ready，确认大纲后交付提示词填 generate；明确自主授权才填 autonomous-complete 并登记九项实际取舍。不能用加载 Skill 代替九问登记。
- 音色、年龄感、口音、语速、表演情绪、配乐与声场等需要选择的内容都纳入这九问，按当前作品出题，不设固定题库。不在正文另外列备选或要求回复数字，不在九问之外追加一轮。角色 A 年轻清亮、沉稳厚重、磁性烟嗓等选项应放在同一道音色题里。已确认或已明确提供的信息沿用，不重复问。
- 明确修改现有提示词（如“更低沉一点”“换成东北口音”）用 audioWorkflowAction=direct-answer 直接交付完整新版，不重走九问。确需重新选择且有对应旧题时用 revise + reopenedQuestions；旧草稿没有九问记录而需要共同选择时用 start 整理为九问，不另开聊天选择题。
- 只说“继续”不等于授权代答；已有三题未答就保留原卡，不新增问题。结构化答案回执已保存的决定不得重问，三轮完成后不得增加第十题。已有录音按角色映射直接引用原文件，无需转写或重新问文字音色。
- 仅提模型名、尚未给创作内容时使用 audioWorkflowAction=direct-answer，加载 Skill 后简短请其提供想法或文案，不凭空写作品。
- “写一段生成音频的提示词”只交付文字；完成九问也不代表请求制作音频，不调用 prepare_media_generation，不准备付费卡。此时 generate 表示交付提示词。员工随后明确要求实际出音频时，切为 audioDeliverable=audio；若大纲已确认，audioWorkflowAction=direct-answer 沿用原决定，随后必须调用 prepare_media_generation（category=voice）显示最终提示词、模型、时长和真实音色附件。对话中的“确认并开始生成”按钮负责提交，不能要求手打确认或只在正文说开始。
- 询问模型知识用 direct-answer；员工明确要求把提示词实际制作成音频时，走对应语音生成流程。生图、改图、图生视频、普通文案、脚本或其它话题按当前要求选择能力，不要求退出口令或模式按钮，不因历史出现模型名就套用音频 Skill。
继续修改当前作品时沿用素材和已确认要求，跨媒介创作按当前目标与可用模型选择合适工具；员工明确点名的模型优先，不支持时说明，不静默替换。`;

/** Public action availability, including previously delivered audio prompts. */
export function audioPromptReadyFromSettings(value: unknown) {
  const source = record(value);
  const interview = record(source?.creativeInterview);
  return source?.seedAudioPromptUsed === true && source.seedAudioDeliverable !== "audio" &&
    interview?.canGenerate === true && interview.answered === 9;
}

/** Recover original voice references across the same audio writing workflow.
 * IDs are context only: the model must select the references and role order for
 * its confirmation card. The generate route rechecks access to each source.
 */
export async function audioPromptReferenceIds(db: D1Database, conversationId: string, userId: string, sourceJobId: string) {
  const rows = await db.prepare(`SELECT a.id FROM director_jobs j
    JOIN director_jobs source ON source.id = ? AND source.conversation_id = j.conversation_id
      AND source.created_by = j.created_by
    JOIN json_each(CASE WHEN json_valid(j.asset_ids) THEN j.asset_ids ELSE '[]' END) ref
    JOIN assets a ON a.id = ref.value
    WHERE j.conversation_id = ? AND j.created_by = ? AND j.agent_role = 'creator'
      AND j.channel_id IS NULL AND j.status = 'completed' AND j.rowid <= source.rowid
      AND json_extract(j.generation_settings, '$.seedAudioPromptUsed') = 1
      AND j.rowid > COALESCE((SELECT MAX(boundary.rowid) FROM director_jobs boundary
        WHERE boundary.conversation_id = j.conversation_id AND boundary.created_by = j.created_by
          AND boundary.agent_role = 'creator' AND boundary.channel_id IS NULL
          AND boundary.status = 'completed' AND boundary.rowid < source.rowid
          AND COALESCE(json_extract(boundary.generation_settings, '$.seedAudioPromptUsed'), 0) != 1), 0)
      AND a.kind = 'audio' AND a.deleted_at IS NULL AND a.status = 'ready'
    ORDER BY j.rowid, CAST(ref.key AS INTEGER)`)
    .bind(sourceJobId, conversationId, userId).all<{ id: string }>();
  return [...new Set(rows.results.map(row => row.id))];
}
